package org.marketreview.nativeapp;
import org.json.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
final class AuctionAnalysisChecks {
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}static List<String> ids(JSONObject r)throws Exception{List<String> out=new ArrayList<>();JSONArray a=r.getJSONArray("patterns");for(int i=0;i<a.length();i++)out.add(a.getJSONObject(i).getString("id"));Collections.sort(out);return out;}
 static void model(JSONArray cases)throws Exception{for(int i=0;i<cases.length();i++){JSONObject c=cases.getJSONObject(i),r=AuctionAnalysisModel.analyze(c.getJSONObject("snapshot"));List<String> expected=new ArrayList<>();JSONArray a=c.getJSONArray("expected");for(int j=0;j<a.length();j++)expected.add(a.getString(j));check(ids(r).equals(expected),"actual old eight formula parity");check(r.getInt("historyCount")==20&&r.getDouble("coverageRatio")==1&&r.getJSONArray("expectedMissingDates").length()==1,"supplied calendar/history coverage");}JSONObject source=cases.getJSONObject(0).getJSONObject("snapshot"),base=AuctionAnalysisModel.analyze(source),ordinary=new JSONObject(source.toString());ordinary.getJSONObject("input").getJSONObject("meta").put("auctionFieldContractVerified",false);check(AuctionAnalysisModel.analyze(ordinary).getString("dataLevel").equals("D0"),"ordinary quote not auction");JSONObject missing=new JSONObject(source.toString());missing.getJSONObject("input").getJSONArray("history").getJSONObject(0).remove("instrumentId");check(AuctionAnalysisModel.analyze(missing).getString("patternStatus").equals("insufficient-history"),"full history ID required");JSONObject conflict=new JSONObject(source.toString()),input=conflict.getJSONObject("input");input.getJSONArray("history").put(new JSONObject(input.getJSONArray("history").getJSONObject(0).toString()).put("matchedAmount",999999));check(AuctionAnalysisModel.analyze(conflict).getInt("historyCount")==19,"conflicting same day excluded");JSONObject future=new JSONObject(source.toString());input=future.getJSONObject("input");JSONArray rows=input.getJSONArray("rows");JSONObject last=rows.getJSONObject(rows.length()-1),extra=new JSONObject(last.toString());String t=AuctionAnalysisModel.stamp(last.getString("time")).plusSeconds(5).toString();extra.put("time",t).put("availableAt",t).put("auctionReferencePrice",1000);rows.put(extra);JSONObject ignored=AuctionAnalysisModel.analyze(future);check(ids(ignored).equals(ids(base))&&ignored.getJSONArray("points").length()==13,"future doesn't change history");JSONObject noCadence=new JSONObject(source.toString());noCadence.getJSONObject("input").getJSONObject("meta").remove("auctionExpectedIntervalMs");check(AuctionAnalysisModel.analyze(noCadence).isNull("coverageRatio"),"cadence not inferred");JSONObject noCalendar=new JSONObject(source.toString());noCalendar.remove("coverage");check(AuctionAnalysisModel.analyze(noCalendar).isNull("expectedMissingDates"),"calendar missing not zero gaps");JSONObject gaps=new JSONObject(source.toString());JSONArray gapRows=gaps.getJSONObject("input").getJSONArray("rows");for(int i=0;i<4;i++)gapRows.remove(4);check(AuctionAnalysisModel.analyze(gaps).getString("patternStatus").equals("insufficient-data"),"missing bins cannot pass coverage");JSONObject revision=new JSONObject(source.toString());JSONArray revisionRows=revision.getJSONObject("input").getJSONArray("rows");revisionRows.put(new JSONObject(revisionRows.getJSONObject(0).toString()).put("auctionReferencePrice",11));check(AuctionAnalysisModel.analyze(revision).getString("dataLevel").equals("D0"),"native revision conflict guard");JSONObject mixed=new JSONObject(source.toString());mixed.getJSONObject("input").getJSONArray("rows").getJSONObject(0).put("instrumentId","SZ:stock:000001");check(AuctionAnalysisModel.analyze(mixed).getString("dataLevel").equals("D0"),"point mixed identity refused");}
 public static void main(String[] args)throws Exception{JSONObject fixture=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8));model(fixture.getJSONArray("cases"));System.out.println("PASS AuctionAnalysis production Java old-eight parity/ordinary split/fullID/conflict/calendar/cadence/future causal; staging only");}
 static void run(FlowInstrumentation f,JSONArray cases)throws Exception{model(cases);AuctionAnalysisScreen[] reopened=new AuctionAnalysisScreen[1];f.ui(()->{try{JSONArray snapshots=new JSONArray();for(int i=0;i<cases.length();i++)snapshots.put(cases.getJSONObject(i).getJSONObject("snapshot"));AuctionAnalysisScreen screen=new AuctionAnalysisScreen(f.activity,()->snapshots);screen.choose(snapshots.getJSONObject(0));check(screen.data.getChildCount()==13,"actual raw point ledger");screen.sectionIndex=1;screen.section.setSelection(1);screen.renderData();check(screen.data.getChildCount()==20,"history ledger");screen.reader.setText(AuctionAnalysisModel.detail(screen.result));screen.show(2);AuctionAnalysisScreen copy=new AuctionAnalysisScreen(f.activity,()->snapshots);copy.restoreState(screen.saveState());check(copy.view==2&&copy.reader.getText().toString().contains("historyAudit"),"complete capture reader recreation");copy.setDarkTheme(true);check(copy.back()&&copy.back()&&!copy.back(),"internal back");reopened[0]=copy;}catch(Exception e){throw new RuntimeException(e);}});f.ui(()->check(reopened[0].sectionIndex==1,"late spinner preserves restored history view"));}
}
